/** PDF 空白单元格（签字栏留白） */
private PdfPCell createPdfBlankCell() {
    PdfPCell cell = new PdfPCell();
    cell.setMinimumHeight(46f);
    cell.setBorderColor(BaseColor.BLACK);
    cell.setBorderWidth(0.8f);
    return cell;
}

/**
 * PDF 签字图片单元格：从签字字段取首个文件路径，走文件服务下载图片并按比例缩放填入签字栏。
 * 字段为空、路径解析失败或取图异常时降级为空白格，绝不抛异常阻断整单 PDF。
 */
private PdfPCell createPdfSignImageCell(String sign) {
    try {
        String path = pickFirstSignPath(sign);
        if (StrUtil.isBlank(path)) {
            return createPdfBlankCell();
        }
        byte[] bytes;
        try (InputStream is = remoteFileService.downloadByFilePath(path).body().asInputStream()) {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            byte[] buffer = new byte[8192];
            int len;
            while ((len = is.read(buffer)) > 0) {
                bos.write(buffer, 0, len);
            }
            bytes = bos.toByteArray();
        }
        if (bytes.length == 0) {
            return createPdfBlankCell();
        }
        Image image = Image.getInstance(bytes);
        image.scaleToFit(180f, 60f);
        PdfPCell cell = new PdfPCell(image, true);
        cell.setMinimumHeight(46f);
        cell.setBorderColor(BaseColor.BLACK);
        cell.setBorderWidth(0.8f);
        cell.setHorizontalAlignment(Element.ALIGN_CENTER);
        cell.setVerticalAlignment(Element.ALIGN_MIDDLE);
        cell.setPadding(4f);
        return cell;
    } catch (Exception e) {
        log.warn("整改任务单 PDF 签字图片处理失败，签字字段={}", sign, e);
        return createPdfBlankCell();
    }
}

/**
 * 从签字字段取首个图片路径：兼容普通字符串、逗号分隔串、JSON 数组/对象、对象数组。
 * 与 G 端 RectifyTaskPreview.vue#pickFirstFilePath 口径一致。
 */
private String pickFirstSignPath(String sign) {
    if (StrUtil.isBlank(sign)) {
        return "";
    }
    String text = sign.trim();
    if (text.startsWith("[") || text.startsWith("{")) {
        try {
            Object parsed = JSON.parse(text);
            if (parsed instanceof JSONArray) {
                JSONArray arr = (JSONArray) parsed;
                return arr.isEmpty() ? "" : pickFirstSignPath(arr.get(0) == null ? null : arr.get(0).toString());
            }
            if (parsed instanceof JSONObject) {
                JSONObject obj = (JSONObject) parsed;
                for (String key : new String[]{"url", "path", "fileUrl"}) {
                    if (obj.containsKey(key) && obj.get(key) != null) {
                        return pickFirstSignPath(obj.get(key).toString());
                    }
                }
                return "";
            }
        } catch (Exception e) {
            log.warn("整改任务单 PDF 签字字段解析失败，签字字段={}", sign, e);
            return "";
        }
    }
    return text.split(",")[0].trim();
}

