function Get-Cred($target) {
    $ptr = [IntPtr]::Zero
    if (-not [WinCred]::CredReadW($target, 1, 0, [ref]$ptr)) { return $null }
    try {
        $c = [Runtime.InteropServices.Marshal]::PtrToStructure($ptr, [type][WinCred+CREDENTIAL])
        $pwBytes = New-Object byte[] $c.CredentialBlobSize
        [Runtime.InteropServices.Marshal]::Copy($c.CredentialBlob, $pwBytes, 0, $c.CredentialBlobSize)
        $pw = [Text.Encoding]::Unicode.GetString($pwBytes)
        $user = [Runtime.InteropServices.Marshal]::PtrToStringUni($c.UserName)
        return @{ user=$user; pass=$pw }
    } finally { [WinCred]::CredFree($ptr) }
}
